import { createContext, useState, useContext } from "react";

// This creates a "shared box" that any part of the app can access
const AccessibilityContext = createContext();

export function AccessibilityProvider({ children }) {
  // This remembers which profile is currently selected
  const [profile, setProfile] = useState("none"); // "none", "lowVision", etc.

  return (
    <AccessibilityContext.Provider value={{ profile, setProfile }}>
      {children}
    </AccessibilityContext.Provider>
  );
}

// This is a shortcut so other files can easily use the shared box
export function useAccessibility() {
  return useContext(AccessibilityContext);
}
